solution.python:
from typing import Optional

# TreeNode is supplied by the LeetCode judge.
class Solution:
    def isBalanced(self, root: Optional["TreeNode"]) -> bool:
        def height_or_failure(node: Optional["TreeNode"]) -> int:
            if node is None:
                return 0

            left_height = height_or_failure(node.left)
            if left_height == -1:
                return -1

            right_height = height_or_failure(node.right)
            if right_height == -1:
                return -1

            if abs(left_height - right_height) > 1:
                return -1
            return 1 + max(left_height, right_height)

        return height_or_failure(root) != -1
